        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "On doit exiger de moi que je cherche la vérité, mais non que je la trouve.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "J'écris de Dieu; je compte sur peu de lecteurs, et n'aspire qu'à quelques suffrages. Si ces pensées ne plaisent à personne, elles pourront n’être que mauvaises; mais je les tiens pour détestables si elles plaisent à tout le monde.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Parce qu'un homme a tort de ne pas croire en Dieu, avons-nous raison de l'injurier? On n'a recours aux invectives que quand on manque de preuves.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "L'homme le plus heureux est celui qui fait le bonheur d'un plus grand nombre d'autres.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Méfiez-vous de celui qui veut mettre de l'ordre. Ordonner, c'est toujours se rendre le maître des autres en les gênant : et les Calabrais sont presque les seuls à qui la flatterie des législateurs n'en ait point encore imposé.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "A. Et la jalousie ? B. Passion d'un animal indigent et avare qui craint de manquer; sentiment injuste de l'homme; conséquence de nos fausses mœurs, et d'un droit de propriété étendu sur un objet sentant, pensant, voulant et libre.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "La vie sauvage est si simple, et nos sociétés sont des machines si compliquées ! L’Otaïtien touche à l’origine du monde et l’Européen touche à sa vieillesse. L’intervalle qui le sépare de nous est plus grand que la distance de l’enfant qui naît à l’homme décrépit. Il n’entend rien à nos usages, à nos lois, ou il n’y voit que des entraves déguisées sous cent formes diverses, entraves qui ne peuvent qu’exciter l’indignation et le mépris d’un être en qui le sentiment de la liberté est le plus profond des sentiments.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Dis-moi si, dans quelque contrée que ce soit, il y a un père qui, sans la honte qui le retient, n'aimât mieux perdre son enfant, un mari qui n'aimât mieux perdre sa femme, que sa fortune et l'aisance de toute sa vie.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Mille hommes qui ne craignent pas pour leur vie, sont plus redoutables que dix mille qui craignent pour leur fortune.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Aucun homme n'a reçu de la nature le droit de commander aux autres. La liberté est un présent du ciel.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Comment s’étaient-ils rencontrés ? Par hasard, comme tout le monde. Comment s’appelaient-ils ? Que vous importe ? D’où venaient-ils ? Du lieu le plus prochain. Où allaient-ils ? Est-ce que l’on sait où l’on va ?", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Si l'on ne dit presque rien dans ce monde, qui soit entendu comme on le dit, il y a bien pis, c'est qu'on n'y fait presque rien qui soit jugé comme on l'a fait.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "C'est qu'il n'y a du danger que pour ceux qui parlent, et je me tais.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Vous êtes quelquefois si profond et si sublime, que je ne vous entends pas.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Jamais aucune religion ne fut aussi féconde en crimes que le christianisme ; depuis le meurtre d'Abel jusqu'au supplice de Calas, pas une ligne de son histoire qui ne soit ensanglantée.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "sachez qu'une allégorie commune quoique neuve, est mauvaise, et qu'une allégorie sublime, n'est bonne qu'une fois. C'est un bon mot usé, dès qu'il est redit", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Elle est belle, très belle de visage et de toute sa personne, belles formes, belle peau, belles mains, de la jeunesse, de la fraicheur, de la noblesse ; je ne sais pour moi ce qu'il fallait au fils de Jacob. Je n'en aurais pas demandé davantage, et je me suis quelquefois contenté de moins. Il est vrai que je n'ai pas l'honneur d'être fils de patriarche.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "On parlera de La Tour ; mais on verra Chardin", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "On s'arrête devant un Chardin, comme d'instinct, comme un voyageur fatigué de sa route va s'asseoir, sans presque s'en apercevoir, dans l'endroit qui lui offre un siège de verdure, du silence, des eaux, de l'ombre et du frais.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Un plaisir qui n’est que pour moi me touche faiblement et dure peu. C’est pour moi et pour mes amis que je lis, que je réfléchis, que j’écris, que je médite, que j’entends, que je regarde, que je sens. Dans leur absence, ma dévotion rapporte tout à eux. Je songe sans cesse à leur bonheur. Une belle ligne me frappe-t-elle ; ils la sauront. Ai-je rencontré un beau trait, je me promets de leur en faire part. Ai-je sous les yeux quelque spectacle enchanteur, sans m’en apercevoir je médite le récit pour eux. Je leur ai consacré l’usage de tous mes sens et de toutes mes facultés ; et c’est peut être la raison pour laquelle tout s’exagère, tout s’enrichit un peu dans mon imagination et dans mon discours. Ils m’en font quelquefois un reproche ; les ingrats !", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "songez que, quoique l'ambroisie dont les dieux du paganisme s'enivraient, fût une boissons très légère, et que la vision béatifique dont nos bienheureux se repaissent, soit une viande fort creuse, ils n'en vient pas moins des êtres dodus, charnus, gras, solides et potelés, et que les fesses de Ganimède et les tétons de la Vierge Marie doivent être aussi bons à prendre qu'à aucun giton, qu'à aucune catin de ce monde pervers.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Les poètes, prophètes et presbytes sont sujets à voir les mouches comme des éléphants ; les philosophes myopes à réduire les éléphants à des mouches. La poésie et la philosophie sont les deux bouts de la lunette.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "cette religion étant, à mon sens, la plus absurde et la plus atroce dans ses dogmes; la plus inintelligible, la plus métaphysique, la plus entortillée et par conséquent la plus sujette à divisions, sectes, schismes, hérésies; la plus funeste à la tranquillité publique, la plus dangereuse pour les souverains par son ordre hiérarchique, ses persécutions et sa discipline; la plus plate, la plus maussade, la plus gothique et la plus triste dans ces cérémonies; la plus puérile et la plus insociable dans sa morale considérée, non dans ce qui lui est commun avec la morale universelle, mais dans ce qui lui est propre et ce qui la constitue morale évangélique, apostolique et chrétienne; la plus intolérante de toutes.", Author = "Denis Diderot" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Denis_Diderot", Text = "Fixez, avec le plus de justesse et d'impartialité que vous pourrez, les prérogatives de l'homme et de la femme ; mais n'oubliez pas que, faute de réflexion et de principes, rien ne pénètre jusqu'à une certaine profondeur de conviction dans l'entendement des femmes ; que les idées de justice, de vertu, de vice, de bonté, de méchanceté, nagent à la superficie de leur âme ; qu'elles ont conservé l'amour-propre et l'intérêt personnel avec toute l'énergie de nature ; et que, plus civilisées que nous en dehors, elles sont restées de vraies sauvages en dedans, toutes machiavélistes, du plus au moins. Le symbole des femmes en général est celle de l'Apocalypse, sur le front de laquelle il est écrit : MYSTÈRE.", Author = "Denis Diderot" },
        };
    }
